with recursive params as (
  select r, ('de3d0001-0000-4000-8000-0000000000' || (20 + r))::uuid as pid, 900000 + r as listing, (array[89, 95, 82, 110, 118, 99])[r] as base
  from generate_series(1, 6) r
), walk(r, n, arrival, nights) as (
  select r, 1, date '2026-03-01' + (abs(hashtext('start' || r)) % 4),
         (select case when h < 10 then 1 when h < 45 then 2 when h < 75 then 3 when h < 90 then 4 else 5 end from (select abs(hashtext('n' || r || ':1')) % 100 h) x)
  from params
  union all
  select r, n + 1,
         arrival + nights + (select case when h < 40 then 0 when h < 70 then 1 when h < 85 then 2 when h < 95 then 3 else 5 end from (select abs(hashtext('g' || r || ':' || n)) % 100 h) x),
         (select case when h < 10 then 1 when h < 45 then 2 when h < 75 then 3 when h < 90 then 4 else 5 end from (select abs(hashtext('n' || r || ':' || (n + 1))) % 100 h) x)
  from walk where arrival < date '2026-12-01'
), priced as (
  select w.r, w.n, w.arrival, w.nights, w.arrival + w.nights as departure, p.pid, p.listing,
         round(p.base * (case extract(month from w.arrival) when 3 then 0.85 when 4 then 0.9 when 5 then 1.0 when 6 then 1.05 when 7 then 1.2 when 8 then 1.25 when 9 then 1.05 when 10 then 0.95 when 11 then 0.85 else 0.9 end)
               * (0.93 + (abs(hashtext('rate' || w.r || ':' || w.n)) % 16) / 100.0)) as rate,
         case when abs(hashtext('ch' || w.r || ':' || w.n)) % 100 < 45 then 'Booking.com' when abs(hashtext('ch' || w.r || ':' || w.n)) % 100 < 85 then 'Airbnb' else 'Direct' end as channel,
         case when abs(hashtext('st' || w.r || ':' || w.n)) % 100 < 90 then 'new' when abs(hashtext('st' || w.r || ':' || w.n)) % 100 < 96 then 'modified' else 'cancelled' end as status,
         (array['A. Patel','M. O''Connor','S. Lindqvist','J. Okafor','R. Hughes','E. Novak','L. Fernandes','K. Tanaka','D. Murphy','H. Schmidt','C. Baptiste','N. Rahman','P. Kowalski','T. Nguyen','B. Sorensen','G. Rossi','F. Dubois','W. Chen','I. Petrova','O. Adeyemi','V. Costa','Y. Haddad','Z. Mahmood','Q. Lee'])[1 + abs(hashtext('gu' || w.r || ':' || w.n)) % 24] as guest,
         91000000 + w.r * 1000 + w.n as res_id,
         3 + abs(hashtext('lead' || w.r || ':' || w.n)) % 38 as lead_days
  from walk w join params p using (r)
), fin as (
  select *, nights * rate as accom, nights * rate + 25 as total,
         case channel when 'Airbnb' then round(nights * rate * 0.153, 2) when 'Booking.com' then round((nights * rate + 25) * 0.15, 2) else 0 end as comm,
         arrival <= current_date as paid
  from priced
)
                                 total_amount, amount_paid, amount_due, channel_commission, hostaway_commission, cleaning_fee, tax_amount, payment_status, fee_lines, synced_at, financials_synced_at, created_at)
