       total, case when paid and status <> 'cancelled' then total else 0 end, case when paid or status = 'cancelled' then 0 else total end, comm, 0, 25, 0,
       case when paid then 'Paid' else 'Unpaid' end, jsonb_build_object('finance', jsonb_build_object('cleaningFee', 25, 'paymentStatus', case when paid then 'Paid' else 'Unpaid' end)),
       timestamptz '2026-09-07 12:10:00+00', timestamptz '2026-09-07 12:10:00+00', (arrival - lead_days)::timestamptz + interval '9 hours'
