insert into public.portfolio_insights (id, user_id, company_id, insights, stats, generated_at, tokens_input, tokens_output) values
  ('404a7990-fb7d-51bc-bd2b-a942401c319d', 'fb1e99c8-ef2f-4903-9bbf-588ead787a6d', null, '[{"title": "9 Ferndale Terrace: \u00a31,785 arrears, 2.6 months", "category": "arrears", "severity": "critical", "body": "Tom Ashby has missed July and August in full and paid \u00a3300 of September. At \u00a3695 a month this is the largest single balance in the portfolio and it is growing. Send the formal arrears letter drafted in Autopilot today and offer a payment plan; if nothing is agreed within 14 days take advice on possession grounds under the Renters Rights Act.", "action_label": "Open arrears letter", "action_link": "#/autopilot"}, {"title": "Two mortgage products end within four months", "category": "expenses", "severity": "warning", "body": "9 Ferndale Terrace (3.29%, ends 31 Oct) and 14 Ashworth Road (4.89%, ends 1 Dec) revert to variable rates of roughly 8.5% if nothing is done, adding about \u00a3430 a month across the two. Combined balance \u00a3136,500 at 52% LTV, so a broker should have good options. Start now: offers take 4 to 6 weeks.", "action_label": "Review mortgages", "action_link": "#/properties"}, {"title": "Elmfield House Flat 4: refurb on track, \u00a34,250 to pay", "category": "opportunity", "severity": "opportunity", "body": "First fix signed off on 30 August with two of three stage payments to come. Re-letting at \u00a3595 (up from \u00a3525) adds \u00a3840 a year and lifts the block to full occupancy. Instruct the EICR and gas certificate for the week of 22 September so the flat can be advertised the day the decorators finish.", "action_label": "Open refurb", "action_link": "#/refurbs"}, {"title": "Quayside Lofts: August RevPAR \u00a381, up 18% on July", "category": "yield", "severity": "info", "body": "The six serviced rooms ran at 78% occupancy in August at an average nightly rate of \u00a3104. Booking.com is 45% of nights but its 15% commission makes Airbnb and direct bookings worth \u00a314 a night more. Push repeat guests to the direct booking page with a 10% code.", "action_label": "Open STL income", "action_link": "#/stl"}]'::jsonb, '{"property_count": 19, "total_value": 1949000, "total_mortgage": 1131100, "total_equity": 817900, "ltv_percent": 58, "monthly_rent": 8050, "annual_rent": 96600, "gross_yield_percent": 7.0, "occupancy_percent": 89, "total_arrears": 2060}'::jsonb, '2026-09-07T06:45:00', 8120, 940);
